"""
views/vm_xml_dialog.py

Full domain XML editor. Loads the inactive XML, lets the user edit it
in a monospace TextView, validates via libvirt on Apply, and redefines
the domain if validation passes.

The VM must be stopped before XML can be applied. A warning is shown
if the VM is running, and Apply is disabled.
"""

import gi
gi.require_version("Gtk", "4.0")
gi.require_version("Adw", "1")

from gi.repository import Gtk, Adw, GLib

from ..backend.libvirt_manager import LibvirtManager, DomainInfo


class VMXmlDialog(Adw.Window):
    def __init__(self, manager: LibvirtManager, info: DomainInfo):
        super().__init__()
        self._mgr  = manager
        self._info = info

        self.set_title(f"Edit XML — {info.meta.get('label', info.name)}")
        # Minimum size — slightly larger than the old fixed size
        self.set_size_request(820, 600)
        # Default size on open
        self.set_default_size(820, 720)
        self.set_resizable(True)

        toolbar = Adw.ToolbarView()
        self.set_content(toolbar)

        header = Adw.HeaderBar()

        btn_close = Gtk.Button(label="Close")
        btn_close.connect("clicked", lambda _: self.close())
        header.pack_start(btn_close)

        # Revert button
        self._btn_revert = Gtk.Button()
        self._btn_revert.set_icon_name("edit-undo-symbolic")
        self._btn_revert.set_tooltip_text("Revert to saved XML")
        self._btn_revert.connect("clicked", self._on_revert)
        header.pack_end(self._btn_revert)

        self._btn_apply = Gtk.Button(label="Apply")
        self._btn_apply.add_css_class("suggested-action")
        self._btn_apply.connect("clicked", self._on_apply)
        self._btn_apply.set_sensitive(not info.is_running)
        header.pack_end(self._btn_apply)

        toolbar.add_top_bar(header)

        body = Gtk.Box(orientation=Gtk.Orientation.VERTICAL, spacing=0)
        toolbar.set_content(body)

        # Status banner
        self._banner = Adw.Banner()
        self._banner.set_revealed(False)
        body.append(self._banner)

        # Running warning — apply locked
        if info.is_running:
            warn = Adw.Banner()
            warn.set_title(
                "This VM is currently running. Stop it before applying XML changes."
            )
            warn.set_revealed(True)
            body.append(warn)

        # Scrollable monospace editor
        scroll = Gtk.ScrolledWindow()
        scroll.set_policy(Gtk.PolicyType.AUTOMATIC, Gtk.PolicyType.AUTOMATIC)
        scroll.set_vexpand(True)
        scroll.set_hexpand(True)
        body.append(scroll)

        self._text_view = Gtk.TextView()
        self._text_view.set_monospace(True)
        self._text_view.set_wrap_mode(Gtk.WrapMode.NONE)
        self._text_view.set_left_margin(12)
        self._text_view.set_right_margin(12)
        self._text_view.set_top_margin(12)
        self._text_view.set_bottom_margin(12)
        self._text_view.add_css_class("card")
        scroll.set_child(self._text_view)

        # Load XML
        self._original_xml: str = ""
        self._load_xml()

    # ------------------------------------------------------------------ #
    # XML loading                                                          #
    # ------------------------------------------------------------------ #

    def _load_xml(self):
        xml = self._mgr.get_domain_xml_pretty(self._info.name)
        if xml is None:
            xml = f"<!-- Could not load XML for {self._info.name} -->"
        # Pretty-print via minidom if available
        xml = self._pretty(xml)
        self._original_xml = xml
        buf = self._text_view.get_buffer()
        buf.set_text(xml)

    @staticmethod
    def _pretty(xml: str) -> str:
        """Indent XML for readability. Falls back to raw if minidom fails."""
        try:
            import xml.dom.minidom as md
            dom = md.parseString(xml.encode())
            pretty = dom.toprettyxml(indent="  ")
            # Remove the <?xml ...?> declaration minidom adds
            lines = [l for l in pretty.splitlines() if not l.startswith("<?xml")]
            # Remove excess blank lines minidom sometimes adds
            result = []
            for line in lines:
                if line.strip() or (result and result[-1].strip()):
                    result.append(line)
            return "\n".join(result)
        except Exception:
            return xml

    # ------------------------------------------------------------------ #
    # Actions                                                              #
    # ------------------------------------------------------------------ #

    def _on_revert(self, _btn):
        buf = self._text_view.get_buffer()
        buf.set_text(self._original_xml)
        self._banner.set_revealed(False)

    def _on_apply(self, _btn):
        if self._info.is_running:
            self._show_banner("Stop the VM before applying XML changes.", error=True)
            return

        buf  = self._text_view.get_buffer()
        xml  = buf.get_text(buf.get_start_iter(), buf.get_end_iter(), False)

        ok, msg = self._mgr.apply_domain_xml(self._info.name, xml)
        if ok:
            # Reload from libvirt so the editor shows the canonical form
            self._load_xml()
            self._show_banner("XML applied successfully.", error=False)
        else:
            self._show_banner(msg, error=True)

    def _show_banner(self, message: str, error: bool):
        self._banner.set_title(message)
        self._banner.set_revealed(True)
        if not error:
            GLib.timeout_add_seconds(4, lambda: self._banner.set_revealed(False) or False)
    def present(self, parent=None):
        """Present the window, setting transient parent if supplied."""
        if parent is not None:
            root = parent.get_root() if hasattr(parent, "get_root") else parent
            if root is not None:
                self.set_transient_for(root)
        self.set_modal(True)
        super().present()
